$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ClosureResults";$case='remaining_m77';$exe="$root\Build\Release\m78-closure-$case.exe"
function Upload($p,$n){for($attempt=0;$attempt -lt 10;$attempt++){try{Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null;return}catch{if($attempt -eq 9){throw};Start-Sleep -Milliseconds 200}}}
try{
if(Test-Path $exe){throw 'Preserve previous continuation binary'};Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-balance_lab-build.json" -OutFile "$out\remaining-m77-link-receipt.json";$build=[IO.File]::ReadAllText("$out\remaining-m77-link-receipt.json")|ConvertFrom-Json;Invoke-WebRequest -UseBasicParsing "$base/reports/m78-closure-balance_lab-m78-closure-balance_lab.exe.bin" -OutFile $exe;if((Get-Item $exe).Length -ne $build.executableBytes -or (Get-FileHash $exe).Hash.ToLower() -ne $build.executableSHA256){throw 'Exact final original M77 binary identity changed'}
$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-closure-v1.json").Content|ConvertFrom-Json;$c=@($m.cases|Where-Object {$_.id -eq 'balance_lab'})[0];$selected=@($c.runs|Where-Object {$_.id -in 'balance-exact-cold-read','balance-new-cold-write','balance-new-cold-read'});$runs=@();$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:JUDAS_DIAGNOSTIC_CONTINUE_WRITE=$null;$env:TEMP="$out\temp";$env:TMP=$env:TEMP;$env:APPDATA="$out\userdata\Roaming";$env:LOCALAPPDATA="$out\userdata\Local"
foreach($r in $selected){$dest=if($r.id -eq 'balance-exact-cold-read'){"$out\balance-exact-cold-final"}else{"$out\balance-new-cold-final"};$mode=$r.arguments[1];$name="m78-closure-final-$($r.id)";if(Test-Path "$out\$name.json"){throw 'Preserve previous final run'}
if($r.copyExactColdFrom){if(Test-Path $dest){throw 'Preserve legacy copied fixture'};if((Get-FileHash "$($r.copyExactColdFrom)\slots\m77.save").Hash.ToLower() -ne $r.expectedSaveSHA256){throw 'Original legacy snapshot changed'};New-Item -ItemType Directory $dest|Out-Null;Copy-Item "$($r.copyExactColdFrom)\project","$($r.copyExactColdFrom)\slots" $dest -Recurse;if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $r.expectedSaveSHA256){throw 'Exact legacy snapshot copy changed'}}
$w=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process $exe -WorkingDirectory "$root\Source" -ArgumentList @($dest,$mode) -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;throw 'Only owned M77 timeout'};$p.Refresh();$exit=$p.ExitCode;$p.Dispose();$w.Stop();$files=@();foreach($f in @(Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'})+@(Get-ChildItem "$dest\slots" -File)){$report="$name-$($f.Name)";Upload $f.FullName $report;$files+=@{path=$f.FullName;reportName=$report;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}};$row=@{run=$name;exitCode=$exit;expectedExitCode=$r.expectedExitCode;seconds=$w.Elapsed.TotalSeconds;executableSHA256=$build.executableSHA256;arguments=@($dest,$mode);files=$files;legacyExpectedSHA256=$r.expectedSaveSHA256};$runs+=$row;$rp="$out\$name.json";$row|ConvertTo-Json -Depth 5|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";if($exit -ne $r.expectedExitCode){throw 'Unexpected unchanged M77 result'}}
$rp="$out\m78-closure-$case-build.json";@{scope='Same already-linked final original M77 executable, remaining unrun rows after disk-full fixture copy. Legacy a106 snapshot exact bytes preserved and expected to fail; fresh current-format corrective step write/read unchanged test/controller/timestep';case=$case;archive=$build.archive;replacementObjects=$build.replacementObjects;reusedExecutableSHA256=$build.executableSHA256;executable=$exe;executableBytes=$build.executableBytes;runs=$runs;generatedFiles=@(@{path=$exe;name=[IO.Path]::GetFileName($exe);bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe).Hash.ToLower()});ownedLargeEvidence=@();freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp));Upload $exe ('m78-closure-'+$case+'-'+[IO.Path]::GetFileName($exe)+'.bin')
}catch{$_|Out-String|Set-Content "$out\m78-closure-$case-error.txt";Upload "$out\m78-closure-$case-error.txt" "m78-closure-$case-error.txt";exit 1}
